import java.util.Arrays;

public class Main {
  public static void main(String[] args) {
    int[] arr = {3, 2, 0, 1};

    // Java muta y sobreescribe el array original
    Arrays.sort(arr);

    System.out.println(Arrays.toString(arr)); // [0 1 2 3]
  }
}

import java.util.Arrays;

public class Main {
  public static void main(String[] args) {
    String[] arr = {"plátano", "cereza", "manzana"};
    Arrays.sort(arr);
    System.out.println(Arrays.toString(arr));
  }
}

// En Java tendrías que iterar cada fila y ordenarla:
int[][] arr = {{3, 2, 4}, {5, 0, 1}};
for(int i = 0; i < arr.length; i++) {
    java.util.Arrays.sort(arr[i]);
}
